#include <stdio.h>

int main(void) {
    unsigned value,field;if(scanf("%u%u",&value,&field)!=2 || value>255 || field>7)return 1;
    printf("%u\n",(value & ~(7u << 2)) | (field << 2));
    return 0;
}
